        var loader = loaderWithFiles({ 'wiki_publisher.json': parentJson, 'wiki_checklist.json': childJson });
        var merged = loader.loadAgentConfig(CHILD_PATH);
        assert.deepEqual(merged.params.cliPrompts, [
