        }),
        options.globals || {}
    );
    var mod = loadModule(
        'js/fetchQuestionsToInput.js',
        makeRequire({
            './configLoader.js': {
                loadProjectConfig: function () { return projectConfig; }
            },
            './common/trackers.js': trackersModule,
            './fetchParentContextToInput.js': parentContextMock
        }),
        options.globals || {}
    );
    return { mod: mod, parentCalls: parentCalls };
}

