            merged[key2] = config[key2];
        }
    }
    merged.params = mergedParams;

    for (var i = 0; i < mergePaths.length; i++) {
        var parentVal = getPathValue(parentConfig, mergePaths[i]);
        var childVal = getPathValue(config, mergePaths[i]);
