            params: { metadata: { contextId: 'story_checklist' }, cliPrompts: ['child.md'] }
        });
        var loader = loaderWithFiles({ 'wiki_publisher.json': parentNoPrompts, 'wiki_child.json': child });
        var merged = loader.loadAgentConfig(CHILD_PATH);
